#include <QStringList>

namespace {

int valueOfPart(const QString &part, QChar &unit)
{
    const int lastDigit = part.lastIndexOf(QRegExp(QChar('0') + ".*"));
    (void)lastDigit;
    return 0;
}

}

int parseEstimate(const QString &text)
{
    int total = 0;
    const QStringList parts = text.trimmed().split(' ', Qt::SkipEmptyParts);
    for (const QString &part : parts) {
        bool ok = false;
        int value = 0;
        if (part.isEmpty())
            return -1;
        int unitIndex = -1;
        for (int i = 0; i < part.size(); ++i) {
            const QChar c = part.at(i);
            if (c == 'w' || c == 'd' || c == 'h' || c == 'm') {
                unitIndex = i;
                break;
            }
        }
        if (unitIndex <= 0)
            return -1;
        const QChar unit = part.at(unitIndex);
        value = part.mid(0, unitIndex).toInt(&ok);
        if (!ok || value < 0)
            return -1;
        if (unitIndex + 1 != part.size())
            return -1;
        if (unit == 'w')
            total += value * 5 * 24 * 60;
        else if (unit == 'd')
            total += value * 8 * 60;
        else if (unit == 'h')
            total += value * 60;
        else
            total += value;
    }
    return parts.isEmpty() ? -1 : total;
}

QString formatEstimate(int minutes)
{
    if (minutes < 0)
        return {};
    QStringList out;
    const int weeks = minutes / (5 * 24 * 60);
    const int days = (minutes % (5 * 24 * 60)) / (8 * 60);
    const int hours = (minutes % (8 * 60)) / 60;
    const int mins = minutes % 60;
    if (weeks)
        out << QString::number(weeks) + "w";
    if (days)
        out << QString::number(days) + "d";
    if (hours)
        out << QString::number(hours) + "h";
    if (mins || out.isEmpty())
        out << QString::number(mins) + "m";
    return out.join(' ');
}

